mapper.select:
SELECT u.*, COALESCE(c.contract_count, 0) AS contract_count FROM unit u LEFT JOIN ( SELECT unit_id, COUNT(*) AS contract_count FROM contract GROUP BY unit_id ) c ON u.unit_id = c.unit_id
AND ( u.unit_name LIKE CONCAT('%', #{params.keyword}, '%') OR u.social_credit_code LIKE CONCAT('%', #{params.keyword}, '%') )
AND u.status = #{params.status}
AND u.credit_level = #{params.creditLevel}
ORDER BY u.created_at DESC

SELECT COUNT(*)
FROM contract
WHERE unit_id = #{unitId}
